<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}$id=filter_var($_POST['request_id']??null,FILTER_VALIDATE_INT);$status=(string)($_POST['status']??'');$notes=trim((string)($_POST['notes']??''));if(!$id||!in_array($status,['Approved','Declined'],true)||strlen($notes)>500||($status==='Declined'&&strlen($notes)<5)){$_SESSION['error']='Choose approve or decline. A decline requires a short explanation.';header('Location: ../?page=staffing');exit;}$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT id,staff_id,start_on,end_on,status FROM staff_leave_requests WHERE id=:id FOR UPDATE');$q->execute(['id'=>$id]);$request=$q->fetch();if(!$request||$request['status']!=='Pending')throw new DomainException('Only pending leave requests can be reviewed.');if($status==='Approved'){$q=$pdo->prepare('SELECT id FROM users WHERE id=:id FOR UPDATE');$q->execute(['id'=>$request['staff_id']]);if(!$q->fetch())throw new DomainException('The staff account no longer exists.');$q=$pdo->prepare("SELECT id FROM staff_leave_requests WHERE staff_id=:staff AND id<>:request AND status='Approved' AND start_on<=:end_on AND end_on>=:start_on LIMIT 1");$q->execute(['staff'=>$request['staff_id'],'request'=>$id,'end_on'=>$request['end_on'],'start_on'=>$request['start_on']]);if($q->fetch())throw new DomainException('This request overlaps other approved leave. Resolve the schedule conflict before approving.');}$q=$pdo->prepare('UPDATE staff_leave_requests SET status=:status,reviewed_by=:reviewer,reviewed_at=NOW() WHERE id=:id AND status=\'Pending\'');$q->execute(['status'=>$status,'reviewer'=>$user['id'],'id'=>$id]);$q=$pdo->prepare('INSERT INTO staff_leave_reviews(leave_request_id,from_status,to_status,notes,reviewed_by) VALUES(:id,\'Pending\',:status,:notes,:user)');$q->execute(['id'=>$id,'status'=>$status,'notes'=>$notes?:null,'user'=>$user['id']]);audit_log($status==='Approved'?'staff.leave_approved':'staff.leave_declined','staff_leave_requests',$id,['status'=>$status]);$pdo->commit();$_SESSION['notice']='Leave request '.$status.'.';}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Staff leave review failed: '.$e->getMessage());$_SESSION['error']='Could not save the leave decision.';}header('Location: ../?page=staffing');exit;
